UPDATE questions SET
  explanation = $EXPL$Correct (A): ASC 820-10-50-2(b) requires disclosure of transfers between Level 1 and Level 2, including amounts and reasons for the transfer. This transparency helps financial statement users understand changes in measurement reliability when inputs shift between hierarchy levels.
